#include <iostream>

template <typename T>
class Pair {
    T first, second;
public:
    Pair(T a, T b) : first(a), second(b) {}
    T sum() const { return first + second; }
};

int main() {
    Pair<int> a(3, 4);
    Pair<double> b(1.5, 2.5);
    std::cout << a.sum() << std::endl;
    std::cout << b.sum() << std::endl;
    return 0;
}
